2	
3	/// A top-level section in the right **activity bar** (the vertical icon rail pinned to the window's
4	/// trailing edge). Each case is one large icon; clicking it shows that section's **pane** in the
5	/// inspector. A pane stacks one or more `InspectorSectionKind` sub-sections via `InspectorSplitView`
6	/// — the Changes pane stacks Changes + Pull Request, the Files pane is a single sub-section. Future
7	/// sections plug in by adding a case + its `subSections`.
8	///
9	/// `allCases` order IS the bar order (top to bottom). Persisted via `Defaults[.activeInspectorSection]`
10	/// as the bare raw string (`PreferRawRepresentable`, matching `SettingsPane`/`DiffViewMode`); a
11	/// stored value matching no case falls back to the key default (`.changes`), so a rename or corrupt
12	/// value degrades gracefully rather than crashing.
13	enum ActivitySection: String, CaseIterable, Identifiable, Defaults.Serializable,
14	  Defaults.PreferRawRepresentable
15	{
16	  case changes
17	  case history
18	  case files
19	
20	  var id: Self { self }
21	
22	  /// The pane title and the bar icon's tooltip / accessibility label.
23	  var label: String {
24	    switch self {
25	    case .changes: return "Changes"
26	    case .history: return "History"
27	    case .files: return "Files"
28	    }
29	  }
30	
31	  /// SF Symbol for the bar icon.
32	  var systemImage: String {
33	    switch self {
34	    case .changes: return "arrow.triangle.branch"
35	    case .history: return "clock.arrow.circlepath"
36	    case .files: return "folder"
37	    }
38	  }
39	
40	  /// The stacked sub-sections this pane shows, top to bottom. More than one → a collapsible/resizable
41	  /// stack (Changes pane = Changes + Pull Request); a single element → one section, no collapse chevron.
42	  var subSections: [InspectorSectionKind] {
43	    switch self {
44	    case .changes: return [.changes, .pullRequest]
45	    case .history: return [.history]
46	    case .files: return [.files]
47	    }
48	  }
