import SwiftUI

/// The inspector's **History** section body (issue #59): a newest-first commit log for the selected
/// workroom, read via `VCSProviding` through the store-owned `HistoryModel`. Lives inside the
/// inspector's scroll view, so it renders a flat `VStack` of rows (like `ChangesPanel`/`FilesPanel`)
/// rather than a `List`. Single-click a row opens the commit's `ChangesetDetailView` as a preview
/// content tab; a quick double-click persists it (the same gate the Changes panel uses).
struct HistoryPanel: View {
  @EnvironmentObject var store: AppStore
  /// Injected + `@ObservedObject` (mirrors `FilesPanel`), NOT read via `store.commitHistory`: the
  /// panel must subscribe to the model's own `@Published` state so its `.loading → .loaded` flip
  /// re-renders the pane. `AppStore` doesn't forward `commitHistory`'s `objectWillChange`, so a plain
  /// `store.commitHistory` read only refreshed when some *unrelated* store change happened to publish
  /// (a status refresh, a reselection, an app refocus) — leaving the loader stuck until then.
  @ObservedObject var model: HistoryModel
  private let theme = ThemeService.shared

  var body: some View {
    Group {
      if store.inspectorTargetID == nil {
        // No active workspace (nothing selected, or the selected workroom has no open tabs) — empty
        // out to match the detail pane's "No terminal" state rather than show a stale last workroom.
        placeholder("No open terminal", systemImage: "clock")
      } else {
        switch model.state {
        case .idle:
          // A workroom is selected (the outer guard handled the nil case), so `.idle` is only the
          // brief pre-focus state before the model loads — show the loader, never "Select a
          // workroom" (which would wrongly imply no selection).
          loadingIndicator
        case .loading where model.commits.isEmpty:
          loadingIndicator
        case .failed(let message):
          placeholder(message, systemImage: "exclamationmark.triangle")
        default:
          if model.commits.isEmpty {
            placeholder("No history", systemImage: "clock")
          } else {
            list
          }
        }
      }
    }
    // Fill the pane (hosted in fill mode) so the inner `ScrollView` has bounded height and scrolls
    // itself — SwiftUI owns the scrolling, which is what lets the divergence accordion animate
    // smoothly (see `list`).
    .frame(maxWidth: .infinity, maxHeight: .infinity, alignment: .top)
    // No container-level `accessibilityIdentifier` here: SwiftUI propagates a container id onto the
    // combined `HistoryRow` leaves, clobbering their own id. The rows carry "HistoryRow"; that the
    // pane is showing is asserted via `inspector.header.History` (the canonical section marker).
    // Point the model at the inspector's active target (nil once all its tabs close → History
    // clears), only while History is the active section. Mirrors FilesPanel; `focus` no-ops when
    // already on the path.
    .task(id: activationKey) {
      guard store.activeInspectorSection == .history else { return }
      // `activate` (not `focus`): on re-entry with the same workroom it pulls fresh (and retries a
      // prior failure), so switching away and back after a terminal commit shows the new log — where
      // `focus` would no-op on the unchanged root. The store's eager `focus` on selection still fires
      // first; `activate`'s settled-state guard means this won't double that fresh load.
      model.activate(store.inspectorTarget.map { URL(fileURLWithPath: $0.path) })
    }
  }

  private var activationKey: String {
    "\(AppStore.targetIDString(for: store.inspectorTargetID) ?? "")"
      + "\u{1F}\(store.activeInspectorSection == .history)"
  }

  /// The changeset tab's title for a commit — its summary, or the short id when it has none.
  private func title(_ commit: VCSCommit) -> String {
    commit.summary.isEmpty ? commit.shortID : commit.summary
  }

  /// The commit rows in a SwiftUI `ScrollView` (the History pane hosts its body in fill mode, so this
  /// owns the scrolling rather than the AppKit `NSScrollView`). SwiftUI owning the scroll is what
  /// makes the per-row divergence accordion animate smoothly — a growing row's height change and the
  /// resulting scroll layout are one SwiftUI transaction, not a fight with an AppKit resize.
  private var list: some View {
    ScrollView {
      VStack(alignment: .leading, spacing: 0) {
        ForEach(model.commits) { commit in
          if commit.isRoot {
            // jj's `root()` shares almost nothing with a real commit row — no author, time, refs,
            // push state, divergence or changeset to open — so it gets its own view rather than a
            // `HistoryRow` body threaded with suppressions.
            HistoryRootRow(commit: commit)
          } else {
            HistoryRow(
              commit: commit,
              // Page-level, so an unpushed row's tooltip can name the origin branch it was measured
              // against instead of saying "origin" generically.
              pushScope: model.pushScope,
              // Open any commit's changeset — the row itself, or one of its divergent siblings.
              // Preview on a single click, persist on a quick double-click (siblings only ever
              // preview).
              open: { target, persist in
                if persist {
                  store.openChangesetPersistent(commitID: target.commitID, title: title(target))
                } else {
                  store.openChangesetPreview(commitID: target.commitID, title: title(target))
                }
              },
              sessions: store.terminals)
          }
        }
        if !model.reachedEnd {
          Button {
            model.loadMore()
          } label: {
            HStack(spacing: 6) {
              if case .loading = model.state {
                ProgressView().controlSize(.small)
              } else {
                Image(systemName: "arrow.down.circle")
              }
              Text("Load more").font(.callout)
            }
            .frame(maxWidth: .infinity, alignment: .center)
            .padding(.vertical, 8)
          }

}

// Replace the default "Show/Hide Sidebar" with a clearer "Projects" label — it's the projects
// sidebar. A `Toggle` (not a plain `toggleSidebar` Button) so the menu shows a checkmark when the
// sidebar is visible; it binds `store.sidebarVisible`, which drives the split view's column
// visibility. Keeps the conventional ⌃⌘S shortcut.
CommandGroup(replacing: .sidebar) {
  Toggle("Projects", isOn: storeFlag(\.sidebarVisible))
    .keyboardShortcut("s", modifiers: [.command, .control])
    .disabled(modalBlocked)
}

CommandGroup(after: .sidebar) {
  // View menu: toggle the right-hand inspector panel as a whole (⌘B), independent of which
  // section is active — the Changes/Files/History/Pull Request toggles below select a section
  // AND open the inspector; this one just shows/hides whatever section was last active.
  Toggle("Inspector", isOn: $showInspector)
    .keyboardShortcut("b", modifiers: [.command])
    .disabled(modalBlocked)

  // View menu: reveal the Changes view. Changes and Pull Request share the **Changes** activity-bar
  // pane (a stack), so "showing" Changes means selecting that pane, opening the inspector, and
  // expanding the Changes sub-section; the checkmark is on only when all three hold. Turning it off
  // just collapses the sub-section (the pane stays open if Pull Request is still showing).
  Toggle(
    "Changes",
    isOn: Binding(
      get: {
        showInspector && store?.activeInspectorSection == .changes
          && !(store?.changesSectionCollapsed ?? true)
      },
      set: { on in
        if on {
          store?.activeInspectorSection = .changes
          showInspector = true
          store?.changesSectionCollapsed = false
        } else {
          store?.changesSectionCollapsed = true
        }
      })
  )
  .keyboardShortcut("c", modifiers: [.command, .option])
  .disabled(modalBlocked)

  // View menu: reveal the Files view (the repo file tree) — its own single-section activity-bar
  // pane, so showing it selects the Files pane and opens the inspector; turning it off hides the
  // pane (Files has no sub-section to collapse). Assigning `activeInspectorSection` in both
  // branches forces the bar + inspector to re-render synchronously (see `AppStore.apply`).
  Toggle(
    "Files",
    isOn: Binding(
      get: { showInspector && store?.activeInspectorSection == .files },
      set: { on in
        store?.activeInspectorSection = .files
        showInspector = on
      })
  )
  .keyboardShortcut("f", modifiers: [.command, .option])
  .disabled(modalBlocked)

  // View menu: reveal the History view (the commit log) — its own single-section activity-bar
  // pane, like Files. (⌥⌘Y — ⌥⌘H is macOS "Hide Others".)
  Toggle(
    "History",
    isOn: Binding(
      get: { showInspector && store?.activeInspectorSection == .history },
      set: { on in
        store?.activeInspectorSection = .history
        showInspector = on
      })
  )
  .keyboardShortcut("y", modifiers: [.command, .option])
  .disabled(modalBlocked)

  // View menu: reveal the Pull Request view — the second sub-section of the Changes pane, so it
  // selects that pane, opens the inspector, and expands the Pull Request sub-section.
  Toggle(
    "Pull Request",
    isOn: Binding(
      get: {
        showInspector && store?.activeInspectorSection == .changes
          && !(store?.prSectionCollapsed ?? true)
      },
      set: { on in
        if on {
          store?.activeInspectorSection = .changes
          showInspector = true
          store?.prSectionCollapsed = false
        } else {
          store?.prSectionCollapsed = true
        }
      })
  )
  .keyboardShortcut("p", modifiers: [.command, .option])
  .disabled(modalBlocked)

  // Theme chooser (issue #36). A menu command can't anchor a popover, so it posts a
  // notification RootView observes to present the picker as a sheet.
  Divider()
  Button("Theme…") { NotificationCenter.default.post(name: .showThemePicker, object: nil) }
    .keyboardShortcut("k", modifiers: [.command, .shift])
    .disabled(modalBlocked)

  // Quick dark/light toggle (issue #57): flip the *currently visible* appearance. From System
  // it resolves the live OS appearance first, so it always inverts what's on screen and lands on
  // a forced mode — repeat presses then flip cleanly (the sidebar button still cycles back to
  // System). Title names the destination so the menu reads as the action it performs.
  Button(theme.toggledLightDark.label + " Mode") {
    theme = theme.toggledLightDark
  }

  /// path means no run command configured. A single path-keyed map (mirrors `collapsedProjects`):
  /// `Defaults` keys are static, so per-project keys aren't an option.
  static let runCommands = Key<[String: RunConfig]>("runCommands", default: [:])

  /// Remembered order of the workroom tab bar, as `TerminalTarget.ID` strings (issue #23, same
  /// encoding as `sidebarSelection`). Terminals don't survive relaunch, so this is just an ordering
  /// hint applied to whatever is currently active — stale ids resolve away harmlessly.
  static let workroomTabOrder = Key<[String]>("workroomsView.tabOrder", default: [])

  /// Global inspector layout (issue #24): which of the inspector's sections (Changes / Files / Pull
  /// Request) are collapsed and the relative heights of the panes, ordered as
  /// `InspectorSectionKind.allCases`. Shared across ALL workrooms and windows — switching the selected
  /// workroom changes the inspector's *content* but never its section collapse/size (a single global
  /// shape, not per-workroom). A stored layout whose entry count doesn't match the current section
  /// count is discarded to the default on load. (Was a per-workroom map keyed by `targetIDString`; a
  /// new key string means old per-workroom data is simply ignored.)
  static let inspectorLayout = Key<InspectorPaneState>(
    "inspector.layout", default: .default)

  /// The app `CFBundleShortVersionString` whose release notes the user has already seen (issue: What's
  /// New). nil on a fresh install / first launch after this feature shipped — recorded silently with
  /// no historical backfill. The What's-New dialog shows only when the running version is newer.
  static let lastSeenVersion = Key<String?>("app.lastSeenVersion", default: nil)

  /// Bounded-retry bookkeeping for the auto What's-New fetch (so a firewalled machine doesn't fire a
  /// doomed GitHub request every launch forever). `whatsNewAttemptVersion` is the version those
  /// attempts were for; the count resets when the running version changes. After
  /// `WhatsNewService.maxAutoAttempts` failures the auto fetch gives up (the menu item still works).
  static let whatsNewAttemptVersion = Key<String?>("app.whatsNewAttemptVersion", default: nil)
  static let whatsNewAttempts = Key<Int>("app.whatsNewAttempts", default: 0)

  /// Diff viewer layout (issue #66): `.unified` (default) or `.sideBySide`. Read by `DiffViewer` at
  /// view-construct time, so the choice applies to newly opened diff tabs (a narrow pane falls back
  /// to unified regardless). Stored as the bare raw string via `DiffViewMode: PreferRawRepresentable`.
  static let diffViewMode = Key<DiffViewMode>("diffViewMode", default: .unified)

  /// Per-workroom display label (issue #41), keyed by the workroom's `targetIDString`
  /// ("wr|<project>|<name>", via `TerminalTarget.workroomID`). A label is a display-only alias —
  /// the real workroom name and its Git/JJ workspace are unchanged. Absence of a key means no
  /// label. Invariant: stored values are always trimmed and non-empty (normalised at the write
  /// boundary in `AppStore.setWorkroomLabel`); a cleared label removes the key rather than storing
  /// "". A single project-scoped map (mirrors `runCommands`): `Defaults` keys
  /// are static, so per-workroom keys aren't an option, and the project-scoped id keeps same-named
  /// workrooms in different projects from colliding. The key *string* `workroomLabels` is a
  /// stored-data contract — keep it byte-for-byte stable once shipped.
  static let workroomLabels = Key<[String: String]>("workroomLabels", default: [:])

  /// The split "Merge" button's chosen strategy (issue #88): create a merge commit (default),
  /// squash, or rebase. Global (not per-project) so the choice persists across projects and
  /// restarts. Stored as the bare raw string via `PRMergeMethod: PreferRawRepresentable`.
  static let prMergeMethod = Key<PRMergeMethod>("prMergeMethod", default: .merge)

  /// The release channel for Sparkle auto-updates (issue #91): stable (default), pre, or nightly.
  /// Drives `SPUUpdaterDelegate.allowedChannels(for:)`, read live so switching the Settings picker
  /// takes effect on the next check. Independent of the Go CLI's own `channel` config: the app is
  /// Sparkle-managed, while the standalone CLI self-updates via `workroom update --channel`. Stored
  /// as the bare raw string via `ReleaseChannel: PreferRawRepresentable`.
  static let releaseChannel = Key<ReleaseChannel>("releaseChannel", default: .stable)
}

/// The global persisted inspector layout: the collapse state and relative pane heights of the
/// sections, ordered as `InspectorSectionKind.allCases` (Changes, Files, Pull Request). `weights`
/// are relative (renormalised among the expanded panes at layout time), so they survive
/// inspector-width/height changes; equal weights == the equal-sections default. A layout whose entry
/// count doesn't match the current section count (e.g. a pre-Files 3-entry layout, or a pre-#118
/// 4-entry layout that still had Notifications) is discarded to this default on load.
struct InspectorPaneState: Codable, Defaults.Serializable, Equatable {
  var collapsed: [Bool]
  var weights: [Double]

}

// MARK: - SwiftUI bridge

/// SwiftUI bridge for `InspectorSplitContainerController`. Each section's header and body are passed
/// as `AnyView`s already carrying their environment (the hosted SwiftUI does not inherit the
/// parent's `@EnvironmentObject`s across `NSHostingController`, so the caller injects them), plus
/// the collapse flags. Arrays are ordered as `InspectorSectionKind.allCases`.
struct InspectorSplitView: NSViewControllerRepresentable {
  var headers: [AnyView]
  var bodies: [AnyView]
  var collapsed: [Bool]
  /// Per-section: whether the pane hosts its body in **fill** mode (the body scrolls itself) rather
  /// than the default `NSScrollView` hosting. History uses fill mode so its inline accordion animates
  /// via SwiftUI without fighting the AppKit scroll container.
  var fills: [Bool]
  /// Identifies the active activity-bar section's sub-section set (its raw value). When it changes,
  /// the pane count/identity differs, so the controller rebuilds its panes rather than reusing them.
  var sectionKey: String
  /// A stable key for the selected workroom (so the controller re-distributes when it switches).
  var workroomKey: String
  /// The selected workroom's persisted relative pane heights (equal by default).
  var weights: [Double]
  /// Reports the new relative pane heights after the user drags a divider, for persistence.
  var onWeightsChanged: ([Double]) -> Void

  func makeNSViewController(context: Context) -> InspectorSplitContainerController {
    let panes = makePanes()
    context.coordinator.panes = panes
    context.coordinator.sectionKey = sectionKey
    let controller = InspectorSplitContainerController()
    controller.onWeightsChanged = onWeightsChanged
    controller.install(panes: panes)
    pushContent(into: panes)
    controller.update(workroomKey: workroomKey, collapsed: collapsed, weights: weights)
    return controller
  }

  func updateNSViewController(_ controller: InspectorSplitContainerController, context: Context) {
    controller.onWeightsChanged = onWeightsChanged
    // Active section changed (or the pane count differs) → rebuild the panes for the new sub-section
    // set before pushing content, so headers/bodies/collapse all line up with the new pane list.
    if context.coordinator.sectionKey != sectionKey
      || context.coordinator.panes.count != headers.count
    {
      let panes = makePanes()
      context.coordinator.panes = panes
      context.coordinator.sectionKey = sectionKey
      controller.rebuild(panes: panes)
    }
    pushContent(into: context.coordinator.panes)
    controller.update(workroomKey: workroomKey, collapsed: collapsed, weights: weights)
  }

  /// Fill the space SwiftUI offers. Without this, SwiftUI sizes the controller to the split's
  /// (tiny) intrinsic content size and the inspector renders as a sliver.
  func sizeThatFits(
    _ proposal: ProposedViewSize, nsViewController: InspectorSplitContainerController,
    context: Context
  ) -> CGSize? {
    proposal.replacingUnspecifiedDimensions(by: CGSize(width: 260, height: 400))
  }

  func makeCoordinator() -> Coordinator { Coordinator() }

  /// Create one pane per section, each pre-configured with its body hosting mode (set BEFORE the
  /// pane's view loads, since `fillsBody` is read in `loadView`).
  private func makePanes() -> [InspectorPaneViewController] {
    (0..<headers.count).map { index in
      let pane = InspectorPaneViewController()
      pane.fillsBody = index < fills.count && fills[index]
      return pane
    }
  }

  private func pushContent(into panes: [InspectorPaneViewController]) {
    guard panes.count == headers.count, panes.count == bodies.count, panes.count == collapsed.count
    else { return }
    for (index, pane) in panes.enumerated() {
      pane.setContent(header: headers[index], body: bodies[index], collapsed: collapsed[index])
    }
  }

  final class Coordinator {
    var panes: [InspectorPaneViewController] = []
    /// The section-set the current `panes` were built for; a change triggers a rebuild.
    var sectionKey: String = ""
  }
}

// MARK: - Section header (the sticky bar)

/// One inspector section's header bar: a disclosure chevron, the title, an optional status
/// indicator, and a trailing action accessory. Tapping anywhere toggles `collapsed`. The chevron
/// rotates (a single glyph) so it never changes width. This is hosted as the pane's fixed sticky
/// header — its body content is hosted separately in the pane's scroll view.
struct SectionHeader<Accessory: View>: View {
  let title: String
  /// The section's collapse binding, or `nil` for a **solo** pane (a section whose activity-bar pane
  /// stacks only itself, e.g. Files) — a solo pane can't collapse, so its header shows no chevron and
  /// is a static label rather than a toggle button.
  var collapsed: Binding<Bool>? = nil
  var indicator: AnyView = AnyView(EmptyView())
  var indicatorLabel: String = ""
  /// The View-menu shortcut that reveals this section (e.g. "⌥⌘C"), shown in the header tooltip for
  /// discoverability. Nil for sections with no command equivalent.
  var shortcut: String? = nil
  @ViewBuilder var accessory: () -> Accessory

  var body: some View {
    Group {
      if let collapsed {
        Button {
          collapsed.wrappedValue.toggle()
        } label: {
          headerLabel(collapsed: collapsed.wrappedValue, showsChevron: true)
        }
        .buttonStyle(.plain)
        .accessibilityLabel(
          "\(title) section, \(collapsed.wrappedValue ? "collapsed" : "expanded")"

