import Defaults
import XCTest

@testable import Workroom

/// `ActivitySection` drives the right activity bar (the vertical icon rail) and, via `subSections`,
/// which stacked panels each pane shows. Three things must hold: `allCases` is the bar order (a silent
/// reorder would move the icons), the `subSections` mapping is exact (it decides what the Changes vs
/// Files pane renders and how the per-workroom collapse/weight vectors are sliced), and a stored raw
/// string matching no case falls back to `.changes` (a rename or corrupt `Defaults` value must not
/// crash or blank the inspector). The fallback is provided by `Defaults` + `PreferRawRepresentable`,
/// and is asserted here against a private probe key rather than the shipped one — see `probe`.
final class ActivitySectionTests: XCTestCase {

  /// A private probe key of the same shape as `Defaults.Keys.activeInspectorSection`, because what the
  /// serialization tests below actually assert is a property of the **type** (`PreferRawRepresentable`
  /// storing the bare raw string, and an unknown one falling back to the key's default) — which a key
  /// nobody else reads proves identically.
  ///
  /// Deliberately not the shipped key: the parallel test workers share one UserDefaults domain, and
  /// writing `inspector.activeSection` from a second class raced `SharedPrefDefaultsTests` (a `.files`
  /// write from here landing between that seam's write and its read — about one failure in five 6-class
  /// parallel iterations). That class is now the suite's only writer of the real key, and it covers the
  /// shipped default. See its class doc.
  private let probe = Defaults.Key<ActivitySection>("test.activeSectionProbe", default: .changes)
  private let probeKey = "test.activeSectionProbe"

  override func tearDown() {
    UserDefaults.standard.removeObject(forKey: probeKey)
    super.tearDown()
  }

  func testAllCasesOrderMatchesBarOrder() {
    XCTAssertEqual(ActivitySection.allCases, [.changes, .history, .files])
  }

  func testEveryCaseHasNonEmptyLabelSystemImageAndShortcut() {
    for section in ActivitySection.allCases {
      XCTAssertFalse(section.label.isEmpty, "\(section) has an empty label")
      XCTAssertFalse(section.systemImage.isEmpty, "\(section) has an empty systemImage")
      XCTAssertFalse(section.shortcutHint.isEmpty, "\(section) has an empty shortcut hint")
    }
  }

  /// The pane composition: Changes stacks Changes + Pull Request; Files is solo. Every listed
  /// sub-section must be non-empty (a pane with no sub-sections would render blank).
  func testSubSectionsMapping() {
    XCTAssertEqual(ActivitySection.changes.subSections, [.changes, .pullRequest])
    XCTAssertEqual(ActivitySection.files.subSections, [.files])
    XCTAssertEqual(ActivitySection.history.subSections, [.history])
    for section in ActivitySection.allCases {
      XCTAssertFalse(section.subSections.isEmpty, "\(section) pane has no sub-sections")
    }
  }

  /// The collapse/weight vectors are stored in `InspectorSectionKind.allCases` order; a pane
  /// slices/writes them back by `storeIndex`, so the indices must be stable.
  func testStoreIndexMatchesCanonicalOrder() {
    XCTAssertEqual(InspectorSectionKind.changes.storeIndex, 0)
    XCTAssertEqual(InspectorSectionKind.files.storeIndex, 1)
    XCTAssertEqual(InspectorSectionKind.pullRequest.storeIndex, 2)
    XCTAssertEqual(InspectorSectionKind.history.storeIndex, 3)
  }

  func testDefaultsToChangesWhenUnset() {
    UserDefaults.standard.removeObject(forKey: probeKey)
    XCTAssertEqual(Defaults[probe], .changes)
  }

  /// Stored as the **bare raw string** (`PreferRawRepresentable`), not a JSON-encoded value — that's
  /// what makes a launch argument / hand-written pref readable, and what the fallback below keys on.
  func testRoundTripsAValidValueAsItsRawString() {
    Defaults[probe] = .files
    XCTAssertEqual(Defaults[probe], .files)
    XCTAssertEqual(UserDefaults.standard.string(forKey: probeKey), "files")
  }

  /// A corrupt/renamed raw string deserialises to `nil`, and `Defaults` falls back to `.changes`.
  func testCorruptStoredValueFallsBackToChanges() {
    UserDefaults.standard.set("bogus", forKey: probeKey)
    XCTAssertEqual(Defaults[probe], .changes)
  }
}

import XCTest

/// Issue #128: the View ▸ Projects/Changes/Files/History/Pull Request keyboard shortcuts didn't
/// reach the app when a TUI (a focused `GhosttySurfaceView`, e.g. running Claude Code) held first
/// responder — `GhosttySurfaceView.isAppShortcut` didn't reserve them, so the terminal swallowed
/// the keystroke before the menu's key-equivalent ever saw it. Separately, ⌥⌘S — the OS-standard
/// "Toggle Sidebar" shortcut (AppKit's `toggleSidebar:`, not bound to our own "Projects" menu item,
/// which uses ⌃⌘S) — popped the hidden native `NavigationSplitView` sidebar column open (truly
/// empty, `Color.clear.frame(width: 0)`, unlike the real `SidebarColumn`'s 240pt floor): RootView
/// keeps that column purely for toolbar/title-bar layering, but AppKit auto-wires its default
/// toggle to it regardless. Fixed by catching ⌥⌘S in the `AppDelegate` `NSEvent` monitor and
/// aliasing it onto our real `sidebarVisible` toggle before it can reach AppKit's responder chain.
///
/// These tests don't assume a specific starting toggle state (the underlying `Defaults` persist
/// across runs against the same Debug app) — each asserts the shortcut flips the state, whichever
/// direction that is, both with and without a focused terminal.
final class ViewMenuShortcutsUITests: XCTestCase {
  override func setUpWithError() throws { continueAfterFailure = false }

  private func launchedApp() -> XCUIApplication {
    let app = XCUIApplication()
    app.launchArguments += ["-WorkroomUITestFixture", "1"]
    app.launchArguments += ["-ApplePersistenceIgnoreState", "YES"]
    app.launch()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 15))
    return app
  }

  private func element(_ app: XCUIApplication, id: String) -> XCUIElement {
    app.descendants(matching: .any).matching(identifier: id).firstMatch
  }

  /// Waits until `el`'s existence matches `want`, so a test can assert a toggle flipped without
  /// knowing which direction it started in (persisted `Defaults` carry over across runs).
  @discardableResult
  private func waitExists(_ el: XCUIElement, _ want: Bool, _ timeout: TimeInterval = 6) -> Bool {
    let p = NSPredicate(format: "exists == %@", NSNumber(value: want))
    return XCTWaiter().wait(
      for: [XCTNSPredicateExpectation(predicate: p, object: el)], timeout: timeout) == .completed
  }

  /// Clicks the first available terminal tab chip to move first responder into its
  /// `GhosttySurfaceView` — the "a TUI is focused" precondition issue #128 is about. Any fixture
  /// terminal works; the assertion only cares that a real Ghostty surface holds focus.
  private func focusATerminal(_ app: XCUIApplication) {
    let chip = app.descendants(matching: .any)
      .matching(NSPredicate(format: "identifier BEGINSWITH %@", "terminal.tab.")).firstMatch
    XCTAssertTrue(chip.waitForExistence(timeout: 10), "a terminal tab chip should exist")
    chip.click()
  }

  /// Asserts a keyboard shortcut flips a section's "shown" state. `Files`/`History` are solo panes
  /// whose "off" path closes the WHOLE inspector (`SectionHeader`'s header has no chevron/collapse
  /// binding), so their header's existence toggles cleanly. `Changes`/`Pull Request` collapse IN
  /// PLACE (their header stays in the tree either way) — `SectionHeader` gives their header an
  /// accessibility label of `"<title> section, collapsed"` / `"...expanded"`
  /// (`InspectorSplitView.swift`), so those two are asserted by label instead of existence.
  private func assertShortcutTogglesSection(
    _ app: XCUIApplication, headerID: String, key: String, modifiers: XCUIElement.KeyModifierFlags,
    collapsible: Bool
  ) {
    let header = element(app, id: headerID)
    if collapsible {
      // Don't require existence upfront: if a DIFFERENT section group is currently active (e.g.
      // Files), this header won't exist yet at all — the shortcut both switches the active group
      // AND expands it, so its label goes from "" (absent) straight to "...expanded".
      let before = header.exists ? header.label : ""
      let beforeDescription = before.isEmpty ? "absent" : before
      app.typeKey(key, modifierFlags: modifiers)
      let p = NSPredicate(format: "label != %@", before)
      let waited = XCTWaiter().wait(
        for: [XCTNSPredicateExpectation(predicate: p, object: header)], timeout: 6)
      XCTAssertEqual(
        waited, .completed,
        "\(headerID)'s expanded/collapsed label should change after the shortcut (was \(beforeDescription))"
      )
    } else {
      let before = header.exists
      app.typeKey(key, modifierFlags: modifiers)
      XCTAssertTrue(
        waitExists(header, !before),
        "\(headerID) should flip from \(before) after the shortcut")
    }
  }

  // MARK: - Bug 1: shortcuts reach the menu even with a TUI focused

  func testChangesFilesHistoryPullRequestShortcutsWorkWithTerminalFocused() {
    let app = launchedApp()
    focusATerminal(app)

    assertShortcutTogglesSection(
      app, headerID: "inspector.header.Changes", key: "c", modifiers: [.command, .option],
      collapsible: true)
    focusATerminal(app)
    assertShortcutTogglesSection(
      app, headerID: "inspector.header.Files", key: "f", modifiers: [.command, .option],
      collapsible: false)
    focusATerminal(app)
    assertShortcutTogglesSection(
      app, headerID: "inspector.header.History", key: "y", modifiers: [.command, .option],
      collapsible: false)
    focusATerminal(app)
    assertShortcutTogglesSection(
      app, headerID: "inspector.header.Pull Request", key: "p", modifiers: [.command, .option],
      collapsible: true)
  }

  // MARK: - Bug 2a: ⌃⌘S (our own Projects shortcut) toggles the real sidebar, terminal-focused or not

  func testProjectsShortcutTogglesSidebarWithTerminalFocused() {
    let app = launchedApp()
    focusATerminal(app)

    let row = element(app, id: "sidebar.project.\(uiTestFixtureProjectName)")
    let before = row.exists
    app.typeKey("s", modifierFlags: [.command, .control])
    XCTAssertTrue(
      waitExists(row, !before),
      "⌃⌘S should toggle the real Projects sidebar even with a terminal focused")
  }

  func testProjectsShortcutTogglesSidebarWithoutTerminalFocused() {
    let app = launchedApp()

    let row = element(app, id: "sidebar.project.\(uiTestFixtureProjectName)")
    XCTAssertTrue(row.waitForExistence(timeout: 10), "the fixture project row should render")
    app.typeKey("s", modifierFlags: [.command, .control])
    XCTAssertTrue(waitExists(row, false), "⌃⌘S should hide the real Projects sidebar")
    app.typeKey("s", modifierFlags: [.command, .control])
    XCTAssertTrue(waitExists(row, true), "⌃⌘S should show the real Projects sidebar again")
  }

  // MARK: - Bug 2b: ⌥⌘S (the OS-standard Toggle Sidebar shortcut) must not open the empty native
  // column — it's aliased onto the same real sidebar toggle instead, terminal-focused or not.

  func testOSStandardToggleSidebarShortcutTogglesRealSidebarWithTerminalFocused() {
    let app = launchedApp()
    focusATerminal(app)

    let row = element(app, id: "sidebar.project.\(uiTestFixtureProjectName)")
    let before = row.exists
    app.typeKey("s", modifierFlags: [.command, .option])
    XCTAssertTrue(
      waitExists(row, !before),
      "⌥⌘S should toggle the real Projects sidebar (not an empty native column), terminal focused")
  }

  func testOSStandardToggleSidebarShortcutTogglesRealSidebarWithoutTerminalFocused() {
    let app = launchedApp()

    let row = element(app, id: "sidebar.project.\(uiTestFixtureProjectName)")
    XCTAssertTrue(row.waitForExistence(timeout: 10), "the fixture project row should render")
    app.typeKey("s", modifierFlags: [.command, .option])
    XCTAssertTrue(waitExists(row, false), "⌥⌘S should hide the real Projects sidebar")
    app.typeKey("s", modifierFlags: [.command, .option])
    XCTAssertTrue(waitExists(row, true), "⌥⌘S should show the real Projects sidebar again")
  }

  // MARK: - Bug 3: ⌥⌘B (secondary Projects sidebar toggle) reaches the app with a TUI focused too

  func testSecondaryProjectsShortcutTogglesSidebarWithTerminalFocused() {
    let app = launchedApp()
    focusATerminal(app)

    let row = element(app, id: "sidebar.project.\(uiTestFixtureProjectName)")
    let before = row.exists
    app.typeKey("b", modifierFlags: [.command, .option])
    XCTAssertTrue(
      waitExists(row, !before),
      "⌥⌘B should toggle the real Projects sidebar even with a terminal focused")
  }

  func testSecondaryProjectsShortcutTogglesSidebarWithoutTerminalFocused() {
    let app = launchedApp()

    let row = element(app, id: "sidebar.project.\(uiTestFixtureProjectName)")
    XCTAssertTrue(row.waitForExistence(timeout: 10), "the fixture project row should render")
    app.typeKey("b", modifierFlags: [.command, .option])
    XCTAssertTrue(waitExists(row, false), "⌥⌘B should hide the real Projects sidebar")
    app.typeKey("b", modifierFlags: [.command, .option])
    XCTAssertTrue(waitExists(row, true), "⌥⌘B should show the real Projects sidebar again")
  }

  // MARK: - Bug 4: ⌘B toggles the Inspector as a whole, independent of which section is active

  func testInspectorShortcutTogglesWholeInspectorWithTerminalFocused() {
    let app = launchedApp()
    focusATerminal(app)

    // Establish a known section (Changes) and ensure the inspector is open, so ⌘B's effect on the
    // header is unambiguous regardless of persisted `Defaults` state from a prior run.
    let header = element(app, id: "inspector.header.Changes")
    app.typeKey("c", modifierFlags: [.command, .option])
    XCTAssertTrue(header.waitForExistence(timeout: 6), "Changes section should be open")

    focusATerminal(app)
    app.typeKey("b", modifierFlags: [.command])
    XCTAssertTrue(
      waitExists(header, false), "⌘B should hide the whole inspector, terminal focused")

    focusATerminal(app)
    app.typeKey("b", modifierFlags: [.command])
    XCTAssertTrue(
      waitExists(header, true),
      "⌘B should restore the inspector back on the Changes section, terminal focused")
  }
}

/// Mirrors `UITestFixture.projectName` — kept as a plain literal here so this file doesn't need
/// `@testable import Workroom` just to read one constant.
private let uiTestFixtureProjectName = "UITestProject"

import XCTest

/// UI test for the right activity bar (the vertical icon rail). Guards the core behaviour: clicking a
/// section icon shows THAT section's pane (and hides the other's), and clicking the already-active
/// icon collapses the content pane while the bar stays. The bar is the swap-pane mechanism, so this
/// is the activity-bar analogue of `SettingsSidebarUITests`.
///
/// Run with `make app-uitest` on a real GUI login session — XCUITest can't drive a headless run, so
/// this is excluded from `make app-test` (the unit gate) via a separate scheme.
final class ActivityBarUITests: XCTestCase {
  override func setUpWithError() throws { continueAfterFailure = false }

  private func launchedApp() -> XCUIApplication {
    let app = XCUIApplication()
    app.launchArguments += ["-WorkroomUITestFixture", "1"]
    app.launchArguments += ["-ApplePersistenceIgnoreState", "YES"]
    app.launch()
    app.activate()
    return app
  }

  /// A bar icon by its accessibility id (`activitySection.<rawValue>`).
  private func icon(_ app: XCUIApplication, _ raw: String) -> XCUIElement {
    app.descendants(matching: .any).matching(identifier: "activitySection.\(raw)").firstMatch
  }

  /// A section header by its accessibility id (`inspector.header.<title>`) — present only while that
  /// sub-section's pane is on screen, so it's the signal that a section is showing.
  private func header(_ app: XCUIApplication, _ title: String) -> XCUIElement {
    app.descendants(matching: .any).matching(identifier: "inspector.header.\(title)").firstMatch
  }

  @discardableResult
  private func waitExists(_ el: XCUIElement, _ want: Bool, _ timeout: TimeInterval = 5) -> Bool {
    let p = NSPredicate(format: "exists == %@", NSNumber(value: want))
    return XCTWaiter().wait(
      for: [XCTNSPredicateExpectation(predicate: p, object: el)], timeout: timeout) == .completed
  }

  /// Clicking each icon swaps the pane: the selected section's header(s) appear AND the other
  /// section's header disappears (proving a swap, not an add). The Changes pane stacks both Changes
  /// and Pull Request headers; the Files pane shows only the Files header.
  ///
  /// Each step is a SWITCH to a different section, which always opens that section's pane (never
  /// toggles it closed), so the test is independent of the persisted open/section state it launches
  /// with (tests share the real "Workroom Dev" defaults domain).
  func testClickingIconsSwapsThePane() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))

    XCTAssertTrue(icon(app, "files").waitForExistence(timeout: 10), "activity bar should render")

    // Files → the Files header; Changes header absent.
    icon(app, "files").click()
    XCTAssertTrue(waitExists(header(app, "Files"), true), "Files pane shows the Files header")

    // Switch to Changes → the Changes + Pull Request stack appears and Files is gone (a swap).
    icon(app, "changes").click()
    XCTAssertTrue(waitExists(header(app, "Changes"), true), "Changes pane shows the Changes header")
    XCTAssertTrue(waitExists(header(app, "Pull Request"), true), "Changes pane stacks Pull Request")
    XCTAssertTrue(waitExists(header(app, "Files"), false), "switching away replaces the Files pane")

    // Switch back to Files → Files returns, the Changes stack is gone.
    icon(app, "files").click()
    XCTAssertTrue(waitExists(header(app, "Files"), true), "Files pane returns")
    XCTAssertTrue(waitExists(header(app, "Changes"), false), "the Changes pane is replaced")
  }

  /// Clicking the ACTIVE icon collapses the content pane (its headers disappear) while the bar icon
  /// itself stays — the VSCode toggle behaviour.
  func testClickingActiveIconCollapsesContent() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))

    let changes = icon(app, "changes")
    XCTAssertTrue(changes.waitForExistence(timeout: 10), "activity bar should render")

    // Put Changes into a known-open state by switching to it from Files (a switch always opens,
    // regardless of the persisted visibility the app launched with).
    icon(app, "files").click()
    XCTAssertTrue(waitExists(header(app, "Files"), true), "Files pane opens")
    changes.click()
    XCTAssertTrue(waitExists(header(app, "Changes"), true), "Changes pane opens")

    // Click the ACTIVE icon → the content collapses, the bar icon stays.
    changes.click()
    XCTAssertTrue(
      waitExists(header(app, "Changes"), false), "clicking the active icon hides content")
    XCTAssertTrue(changes.exists, "the bar icon stays visible after collapsing the pane")
  }

  /// History (issue #59) is its own bar section, not a tab inside Changes: clicking its icon swaps
  /// the History pane in (its header + the `HistoryPanel` body appear) and replaces whatever pane
  /// was showing — the same swap contract as Changes/Files, proving History joined the rail as a
  /// peer section rather than being nested under another.
  func testHistorySectionSwapsIntoView() throws {
    let app = launchedApp()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))

    XCTAssertTrue(icon(app, "history").waitForExistence(timeout: 10), "History icon should render")

    // Prime with Files so the next History click is guaranteed a SWITCH (which always opens),
    // independent of whatever section the shared "Workroom Dev" defaults launched active — clicking
    // an already-active icon toggles it closed, so we can't assert on this priming click itself.
    icon(app, "files").click()

    icon(app, "history").click()
    XCTAssertTrue(waitExists(header(app, "History"), true), "History pane shows the History header")
    XCTAssertTrue(waitExists(header(app, "Files"), false), "switching away replaces the Files pane")

    // Switch back to Files (Files ≠ the now-active History → a switch, opens) → History is gone.
    icon(app, "files").click()
    XCTAssertTrue(waitExists(header(app, "Files"), true), "Files pane returns")
    XCTAssertTrue(waitExists(header(app, "History"), false), "the History pane is replaced")
  }
}

