3	/// Store-owned state for the History pane (issue #59): a paged, newest-first commit log for the
4	/// selected workroom, read through `VCSProviding`. Re-pointed on selection (like `FileTreeModel`);
5	/// refreshes on demand. Pagination re-fetches a growing prefix and replaces the list (DAG-safe —
6	/// decision A1: a jj merge graph makes cursor pagination lossy), so there are no dupes/gaps.
7	@MainActor
8	final class HistoryModel: ObservableObject {
9	  enum State: Equatable {
10	    case idle  // no workroom selected
11	    case loading
12	    case loaded
13	    case failed(String)
14	
15	    /// True once a load has *settled* into a result (loaded or failed) — the states from which
16	    /// `activate` should re-read on re-entry, vs `.idle`/`.loading` (nothing to refresh yet / a load
17	    /// is already in flight).
18	    var isSettled: Bool {
19	      switch self {
20	      case .loaded, .failed: return true
21	      case .idle, .loading: return false
22	      }
23	    }
24	  }
25	
26	  @Published private(set) var commits: [VCSCommit] = []
27	  @Published private(set) var reachedEnd = false
28	  @Published private(set) var state: State = .idle
29	  /// What the page's push states were measured against — page-level, so the rows can word their
30	  /// unpushed tooltip with the actual origin branch name. `nil` ⇒ nothing to compare against.
31	  @Published private(set) var pushScope: VCSPushScope?
32	
33	  private let pageSize: Int
34	  private let resolve: @Sendable (URL) throws -> VCSProviding
35	  private(set) var root: URL?
36	  private var task: Task<Void, Never>?
37	
38	  init(
39	    pageSize: Int = 100,
40	    resolve: @escaping @Sendable (URL) throws -> VCSProviding = { try VCS.provider(for: $0) }
41	  ) {
42	    self.pageSize = pageSize
43	    self.resolve = resolve
44	  }
45	
46	  /// Point the model at a repo (or clear it with `nil`). No-op if already focused there. Loads the
47	  /// first page.
48	  func focus(_ root: URL?) {
49	    guard self.root != root else { return }
50	    self.root = root
51	    commits = []
52	    reachedEnd = false
53	    guard root != nil else {
54	      task?.cancel()
55	      state = .idle
56	      return
57	    }
58	    load(limit: pageSize)
59	  }
60	
61	  /// Reload the currently-shown range (on pane-appear / app-focus / the refresh button).
62	  func refresh() {
63	    guard root != nil else { return }
64	    load(limit: max(pageSize, commits.count))
65	  }
66	
67	  /// Ensure fresh data when the History section (re)activates (the panel's `.task`). On a genuine
68	  /// re-entry — same root and a load already *settled* (loaded OR failed) — pull fresh; otherwise
69	  /// defer to `focus` (loads a new root, no-ops mid-load on the same one). The `isSettled` guard does
70	  /// double duty: it prevents a redundant second load when the store just called `focus` eagerly on
71	  /// selection/section-entry (state `.loading`), and it retries after a transient `.failed` (plain
72	  /// `focus` would no-op on the same root and leave the pane stuck showing the error).
73	  func activate(_ root: URL?) {
74	    if self.root == root, root != nil, state.isSettled {
75	      refresh()
76	    } else {
77	      focus(root)
78	    }
79	  }
80	
81	  /// Grow the page by one `pageSize` (the "Load more" affordance).
82	  func loadMore() {
83	    guard root != nil, !reachedEnd, state != .loading else { return }
84	    load(limit: commits.count + pageSize)
85	  }
86	
87	  /// Await the in-flight load — for tests and for a view that wants to sequence after a refresh.
88	  func awaitCurrentLoad() async { await task?.value }
89	
