91	    guard let root else { return }
92	    task?.cancel()
93	    state = .loading
94	    let resolve = self.resolve
95	    task = Task { [weak self] in
96	      do {
97	        // The provider's log read blocks its thread (jj-lib over UniFFI / libgit2). Run it on GCD via
