import XCTest

@testable import Workroom

/// Live History refresh (issue #59 follow-up): a commit / bookmark / ref move in a project's VCS
/// metadata dir trips the per-project watcher → `handleRootBranchChange`, which now repaints the
/// History log **when the inspector is visible, on History, and its target belongs to that project** —
/// independent of whether the branch label changed (a plain commit usually leaves it unchanged). Also
/// covers the app-refocus safety net `refreshHistoryIfActive`.
///
/// The commit log itself is driven through an injected `HistoryModel` backed by a counting provider,
/// so "did a refresh fire?" is observable as a `log` call count — no real repo needed for the gating
/// logic. `runBlocking` reads run off-main, so each assertion awaits `commitHistory.awaitCurrentLoad`.
///
/// Both halves of the gate are pinned **per store** — `inspectorVisibleOverrideForTesting` and
/// `isolatesInspectorSectionForTesting` — never by writing the shared inspector settings: the parallel
/// workers share one UserDefaults domain, so this class used to leave its `showInspector` /
/// `inspector.activeSection` values inside whatever unrelated class ran beside it. (The old
/// save/restore here couldn't have helped even in serial: it restored `"activeInspectorSection"`,
/// which is not the key — the real one is `"inspector.activeSection"`.)
@MainActor
final class HistoryLiveRefreshTests: XCTestCase {

  // MARK: harness

  /// Counts `log` calls (the observable "a load fired" signal). Lock-guarded + `@unchecked Sendable`
  /// because `log` runs off-main via `runBlocking`; tests serialize with `awaitCurrentLoad`.
  private final class CountingProvider: VCSProviding, @unchecked Sendable {
    private let lock = NSLock()
    private var _count = 0
    var logCount: Int { lock.withLock { _count } }
    func log(root: URL, limit: Int) throws -> VCSHistoryPage {
      lock.withLock { _count += 1 }
      return VCSHistoryPage(commits: [], reachedEnd: true)
    }
    func changeset(root: URL, commitID: String) async throws -> VCSChangeset {
      throw VCSError.io("x")
    }
    func fileDiff(root: URL, commitID: String, path: String) async throws -> String {
      throw VCSError.io("x")
    }
    func workingFileDiff(root: URL, path: String, base: VCSWorkingDiffBase) async throws -> String {
      throw VCSError.io("x")
    }
    func fileContent(root: URL, rev: String, path: String) async throws -> String? { nil }
    func currentRef(root: URL) async throws -> VCSRef { .none }
  }

  private func project(_ path: String, workrooms: [String]) -> Project {
    Project(
      path: path, vcs: "git",
      workrooms: workrooms.map {
        Workroom(name: $0, path: "\(path)/\($0)", vcsName: "workroom/\($0)", warnings: [])
      })
  }

  private func wr(_ name: String, in path: String) -> SidebarID {
    .workroom(project: path, name: name)
  }

  /// A store with a counting `commitHistory`, one workroom-with-a-tab selected, the inspector visible
  /// and on History (so `inspectorTargetID` is non-nil and the model is focused → `root != nil`, the
  /// precondition for `refresh` to actually load). Returns the store + the counting provider.
  private func activeHistoryStore(
    projects: [Project], select path: String, workroom name: String
  ) async -> (AppStore, CountingProvider) {
    let provider = CountingProvider()
    let store = AppStore(commitHistory: HistoryModel(resolve: { _ in provider }))
    store.terminals.makeView = { _, cwd, command in
      GhosttySurfaceView(workingDirectory: cwd, command: command, spawnsSurface: false)
    }
    store.projects = projects
    store.inspectorVisibleOverrideForTesting = true
    store.isolatesInspectorSectionForTesting = true
    store.activeInspectorSection = .history
    // Give the selection a tab so `selectionHasTabs` (and thus `inspectorTargetID`) is non-nil.
    store.terminals.addTab(for: store.target(for: wr(name, in: path))!)
    // Selecting fires the didSet that focuses `commitHistory` (section == .history) → the first load.
    store.selectedTargetID = wr(name, in: path)
    await store.commitHistory.awaitCurrentLoad()
    return (store, provider)
  }

  // MARK: live watcher path

  func testMetadataChangeRefreshesHistoryEvenWhenLabelUnchanged() async {
    let (store, provider) = await activeHistoryStore(
      projects: [project("/a", workrooms: ["solo"])], select: "/a", workroom: "solo")
    XCTAssertEqual(store.inspectorTargetID, wr("solo", in: "/a"))
    let before = provider.logCount

    store.handleRootBranchChange(projectID: store.projects[0].id)
    await store.commitHistory.awaitCurrentLoad()

    XCTAssertEqual(
      provider.logCount, before + 1,
      "a metadata change for the shown workroom's project must refresh History, even though a normal "
        + "commit leaves the branch label unchanged (the placement-before-the-label-return guard)")
  }

  func testMetadataChangeInOtherProjectDoesNotRefresh() async {
    let (store, provider) = await activeHistoryStore(
      projects: [project("/a", workrooms: ["solo"]), project("/b", workrooms: ["other"])],
      select: "/a", workroom: "solo")
    let before = provider.logCount
    let otherProject = store.projects.first { $0.path == "/b" }!

    store.handleRootBranchChange(projectID: otherProject.id)
    await store.commitHistory.awaitCurrentLoad()

    XCTAssertEqual(
      provider.logCount, before, "a change in a DIFFERENT project must not refresh this History")
  }

  func testMetadataChangeWhileInspectorHiddenDoesNotRefresh() async {
    let (store, provider) = await activeHistoryStore(
      projects: [project("/a", workrooms: ["solo"])], select: "/a", workroom: "solo")
    store.inspectorVisibleOverrideForTesting = false  // still on .history, but the pane is hidden
    let before = provider.logCount

    store.handleRootBranchChange(projectID: store.projects[0].id)
    await store.commitHistory.awaitCurrentLoad()

    XCTAssertEqual(
      provider.logCount, before, "a hidden inspector must not run background History reads")
  }

  func testMetadataChangeWhileNotOnHistoryDoesNotRefresh() async {
    let (store, provider) = await activeHistoryStore(
      projects: [project("/a", workrooms: ["solo"])], select: "/a", workroom: "solo")
    store.activeInspectorSection = .changes  // switched off History
    let before = provider.logCount

    store.handleRootBranchChange(projectID: store.projects[0].id)
    await store.commitHistory.awaitCurrentLoad()

    XCTAssertEqual(provider.logCount, before, "off-History must not refresh the log")
  }

  // MARK: app-refocus safety net

  func testRefreshHistoryIfActiveRefreshesOnlyWhenVisibleAndHistory() async {
    let (store, provider) = await activeHistoryStore(
      projects: [project("/a", workrooms: ["solo"])], select: "/a", workroom: "solo")

    let before = provider.logCount
    store.refreshHistoryIfActive()  // visible + History → refreshes
    await store.commitHistory.awaitCurrentLoad()
    XCTAssertEqual(provider.logCount, before + 1)

    store.inspectorVisibleOverrideForTesting = false
    store.refreshHistoryIfActive()  // hidden → no-op
    await store.commitHistory.awaitCurrentLoad()
    XCTAssertEqual(
      provider.logCount, before + 1, "hidden inspector → refreshHistoryIfActive no-ops")
  }
}

import XCTest

@testable import Workroom

/// The end-to-end claim the unpushed badge makes: **push, and it clears** — without touching the UI.
///
/// Unlike `HistoryLiveRefreshTests` (which counts `log` calls through a stub to test the gating logic),
/// this drives a REAL git repo through the REAL `GitProvider`, so the assertion is about the push state
/// actually flipping after a push.
///
/// **Scope, stated honestly.** It invokes `AppStore.handleRootBranchChange` directly, which is the
/// callback the per-project `WorkroomFileWatcher` fires. So it proves the refresh path recomputes push
/// state; it does NOT prove FSEvents delivers the event (that the watcher points at the right directory
/// is `WorkroomFileWatcherTests`' and `AppStore.vcsMetadataDir`'s business — a push from a workroom
/// writes `refs/remotes/*` into the project's shared `.git`, which is what's watched).
@MainActor
final class HistoryPushRefreshTests: XCTestCase {
  private var dirs: [String] = []

  override func tearDown() {
    for d in dirs { try? FileManager.default.removeItem(atPath: d) }
    dirs = []
    super.tearDown()
  }

  // MARK: - fixture

  private func tempDir() -> String {
    let d = NSTemporaryDirectory() + "wr-pushref-\(UUID().uuidString)"
    try? FileManager.default.createDirectory(atPath: d, withIntermediateDirectories: true)
    dirs.append(d)
    return d
  }

  @discardableResult
  private func sh(_ cmd: String, in dir: String) -> (out: String, exit: Int32) {
    let p = Process()
    p.executableURL = URL(fileURLWithPath: "/bin/sh")
    p.arguments = ["-c", cmd]
    p.currentDirectoryURL = URL(fileURLWithPath: dir)
    var env = ProcessInfo.processInfo.environment
    env["GIT_CONFIG_GLOBAL"] = "/dev/null"
    env["GIT_CONFIG_SYSTEM"] = "/dev/null"
    env["PATH"] = ShellEnvironment.path()
    p.environment = env
    let pipe = Pipe()
    p.standardOutput = pipe
    p.standardError = pipe
    do { try p.run() } catch { return ("", -1) }
    let data = pipe.fileHandleForReading.readDataToEndOfFile()
    p.waitUntilExit()
    return (String(decoding: data, as: UTF8.self), p.terminationStatus)
  }

  /// A repo with `pushed` on `origin/main` and one local-only commit on top. Returns the work tree.
  private func repoWithLocalCommit() throws -> String {
    struct MissingTool: Error {}
    if sh("command -v git", in: NSTemporaryDirectory()).exit != 0 {
      XCTFail("`git` is required for this test")
      throw MissingTool()
    }
    let root = tempDir()
    sh(
      """
      git init -q --bare bare.git
      git clone -q bare.git work
      cd work && git config user.email a@b.c && git config user.name t \
        && git checkout -q -b main && echo one > a.txt && git add . && git commit -qm pushed \
        && git push -qu origin main \
        && echo two > b.txt && git add . && git commit -qm localwork
      """, in: root)
    return root + "/work"
  }

  /// A store whose History pane is live on `path` (inspector visible, section History, the workroom has
  /// a tab so `inspectorTargetID` resolves) reading through the real `GitProvider`. Both halves of that
  /// gate are pinned per store rather than written to the shared inspector settings — see
  /// `AppStore.inspectorVisibleOverrideForTesting`.
  private func liveHistoryStore(on path: String) async -> AppStore {
    let store = AppStore(commitHistory: HistoryModel(resolve: { _ in GitProvider() }))
    store.terminals.makeView = { _, cwd, command in
      GhosttySurfaceView(workingDirectory: cwd, command: command, spawnsSurface: false)
    }
    // One project whose single "workroom" IS the repo itself — enough for the History pane, and it keeps
    // the fixture to one real repo.
    store.projects = [
      Project(
        path: path, vcs: "git",
        workrooms: [
          Workroom(name: "repo", path: path, vcsName: "main", warnings: [])
        ])
    ]
    store.inspectorVisibleOverrideForTesting = true
    store.isolatesInspectorSectionForTesting = true
    store.activeInspectorSection = .history
    let id = SidebarID.workroom(project: path, name: "repo")
    store.terminals.addTab(for: store.target(for: id)!)
    store.selectedTargetID = id
    await store.commitHistory.awaitCurrentLoad()
    return store
  }

  private func state(_ store: AppStore, _ summary: String) -> VCSPushState? {
    store.commitHistory.commits.first { $0.summary == summary }?.pushState
  }

  // MARK: - the flow

  func testPushClearsTheUnpushedStateOnRefresh() async throws {
    let repo = try repoWithLocalCommit()
    let store = await liveHistoryStore(on: repo)

    XCTAssertEqual(state(store, "localwork"), .unpushed, "the local commit starts unpushed")
    XCTAssertEqual(state(store, "pushed"), .pushed)
    XCTAssertEqual(store.commitHistory.pushScope?.refName, "origin/main")

    // Push from the repo, as a terminal in a workroom would.
    XCTAssertEqual(sh("git push -q origin main", in: repo).exit, 0)

    // The watcher's callback: a ref moved under the project's VCS metadata dir.
    store.handleRootBranchChange(projectID: store.projects[0].id)
    await store.commitHistory.awaitCurrentLoad()

    XCTAssertEqual(
      state(store, "localwork"), .pushed,
      "after a push the refresh must recompute push state, not reuse the old page")
    XCTAssertTrue(
      store.commitHistory.commits.allSatisfy { !$0.showsUnpushedBadge },
      "no row badges once everything is on origin")
  }

  /// The reverse direction, so the test can't pass by simply reporting `.pushed` for everything: a NEW
  /// local commit after the refresh must badge again.
  func testNewLocalCommitBadgesAgainAfterRefresh() async throws {
    let repo = try repoWithLocalCommit()
    let store = await liveHistoryStore(on: repo)
    XCTAssertEqual(sh("git push -q origin main", in: repo).exit, 0)
    store.handleRootBranchChange(projectID: store.projects[0].id)
    await store.commitHistory.awaitCurrentLoad()
    XCTAssertTrue(store.commitHistory.commits.allSatisfy { !$0.showsUnpushedBadge })

    sh("echo three > c.txt && git add . && git commit -qm afterpush", in: repo)
    store.handleRootBranchChange(projectID: store.projects[0].id)
    await store.commitHistory.awaitCurrentLoad()

    XCTAssertEqual(state(store, "afterpush"), .unpushed)
    XCTAssertEqual(
      store.commitHistory.commits.filter(\.showsUnpushedBadge).map(\.summary), ["afterpush"])
  }
}

