/// Single-clicking a History row opens the commit's changeset detail: the detail view, its
/// changed-file list (≥1 row), and a rendered diff (unified `diff.line` or side-by-side
/// `diff.side.left`).
func testHistoryRowOpensChangesetDetail() throws {
  let app = launchedApp()
  XCTAssertTrue(app.wait(for: .runningForeground, timeout: 10))
  openHistory(app)

  els(app, "HistoryRow").element(boundBy: 0).click()

  XCTAssertTrue(waitExists(el(app, "ChangesetDetail")), "the changeset detail opens as a tab")

  // The header shows the changeset's +/- line-count summary (fixture: 24 insertions, 8 deletions).
  // It renders as a combined StaticText whose content is its `value` (the header's `ChangesetDetail`
  // id propagates onto the leaf, so match on the spoken count text, not the id).
  let summary = app.descendants(matching: .any).matching(
    NSPredicate(format: "value CONTAINS %@", "24 insertions, 8 deletions")
  ).firstMatch
  XCTAssertTrue(waitExists(summary), "the header shows the +/- line-count summary")

  XCTAssertTrue(
    els(app, "ChangesetFileRow").element(boundBy: 0).waitForExistence(timeout: 8),
    "the changed-file list renders")
  let diffLine = els(app, "diff.line").element(boundBy: 0)
  let sideLine = els(app, "diff.side.left").element(boundBy: 0)
  XCTAssertTrue(
    waitExists(diffLine) || sideLine.exists,
    "the selected file's diff renders (unified or side-by-side)")
}

/// A double-click on a History row PERSISTS its changeset tab: opening a different commit's preview
/// afterward adds a second tab rather than retargeting the first (which a preview would). Asserted
/// via the two tab chips (`terminal.tab.<title>`) coexisting.
    toggle.waitForExistence(timeout: 8), "the divergent row shows the diverges disclosure")

  // Collapsed: the sibling copies are hidden until the disclosure is opened.
  XCTAssertFalse(
    els(app, "HistoryDivergentSibling").element(boundBy: 0).exists,
    "divergent siblings stay hidden until expanded")

  toggle.click()

  // Expanded: both off-line copies appear, labelled with their jj offsets (e.g. `wqp/1`).
  XCTAssertTrue(
    els(app, "HistoryDivergentSibling").element(boundBy: 1).waitForExistence(timeout: 6),
